From 632bada9f1e04ff4c1391445c90d0eeed6fd3170 Mon Sep 17 00:00:00 2001
From: Sebastian Rasmussen <sebras@gmail.com>
Date: Fri, 7 Dec 2018 18:12:23 +0100
Subject: [PATCH] Bug 700384: Indicate error upon error, do not just warn.

Building a Huffman table failed, this was correctly detected,
but success was indicated to the caller causing a reference
template to be left uninitialized, which later on caused the
generic refinement region decoder attempt to use this
uninitialized data. This was reported by MSAN.

Thanks to oss-fuzz for reporting.
---
 jbig2_text.c | 4 ++--
 1 file changed, 2 insertions(+), 2 deletions(-)

diff --git a/jbig2_text.c b/jbig2_text.c
index 910ad98..e080777 100644
--- a/jbig2_text.c
+++ b/jbig2_text.c
@@ -219,9 +219,9 @@ cleanup1:
         jbig2_release_huffman_table(ctx, runcodes);

         if (SBSYMCODES == NULL) {
-            jbig2_error(ctx, JBIG2_SEVERITY_WARNING, segment->number, "failed to construct symbol ID huffman table");
+            code = jbig2_error(ctx, JBIG2_SEVERITY_WARNING, segment->number, "failed to construct symbol ID huffman table");
             jbig2_huffman_free(ctx, hs);
-            return ((code != 0) ? code : -1);
+            return code;
         }
     }

